WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock, COALESCE(quantity, 0) AS quantity_filled FROM inventory WHERE last_restock > DATE '2024-01-15'), with_windows AS (SELECT *, NTILE(5) OVER w_grp AS quantity_filled_bucket, ROW_NUMBER() OVER w_part AS row_seq, MIN(quantity) OVER (PARTITION BY product_id, store_id) AS product_id_min_quantity, LAST_VALUE(quantity_filled) IGNORE NULLS OVER (PARTITION BY product_id, store_id ORDER BY days_since_last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity_filled, CUME_DIST() OVER (ORDER BY quantity DESC) AS quantity_cume_dist FROM base WINDOW w_grp AS (PARTITION BY store_id ORDER BY quantity_filled DESC, id), w_part AS (PARTITION BY product_id, store_id ORDER BY last_restock DESC, id)), filtered AS (SELECT id, store_id, product_id, quantity, quantity_filled_bucket, row_seq, product_id_min_quantity, last_known_quantity_filled, quantity_cume_dist, ROUND(quantity_filled_bucket * 1.1, 2) AS adjusted_quantity_filled_bucket, CEIL(product_id_min_quantity) AS product_id_min_quantity_whole FROM with_windows WHERE last_restock > DATE '2024-03-30' AND quantity_filled >= 57), filtered_inventory AS (SELECT id, store_id, product_id, quantity_filled_bucket, row_seq, last_known_quantity_filled, quantity_cume_dist, product_id_min_quantity + quantity_cume_dist AS product_id_min_quantity_plus_quantity_cume_dist, adjusted_quantity_filled_bucket * row_seq AS adjusted_quantity_filled_bucket_times_row_seq FROM filtered WHERE product_id_min_quantity BETWEEN 88 AND 137), valid AS (SELECT id, product_id, quantity_filled_bucket, row_seq, last_known_quantity_filled, CASE WHEN adjusted_quantity_filled_bucket_times_row_seq >= 65 THEN 'High' WHEN adjusted_quantity_filled_bucket_times_row_seq >= 36 THEN 'Medium' ELSE 'Low' END AS adjusted_quantity_filled_bucket_times_row_seq_tier FROM filtered_inventory WHERE quantity_filled_bucket = 4), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_known_quantity_filled DESC NULLS LAST, id) AS latest_rank FROM valid) t WHERE latest_rank = 1) SELECT id, quantity_filled_bucket, row_seq, last_known_quantity_filled, adjusted_quantity_filled_bucket_times_row_seq_tier, latest_rank FROM latest ORDER BY row_seq DESC
